TgVal debugger___gdb_pretty_printers(void) {
    TgVal s = tg_str_from_cstr("# Tangerine GDB pretty printers\\n");
    s = tg_str_concat(s, tg_str_from_cstr("import gdb\\nimport gdb.printing\\n\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("class TgStringPrinter:\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("    def __init__(self, val):\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("        self.val = val\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("    def to_string(self):\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("        ptr = self.val['ptr']\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("        length = int(self.val['len'])\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("        return ptr.string(length=length)\\n\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("class TgArrayPrinter:\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("    def __init__(self, val):\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("        self.val = val\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("    def to_string(self):\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("        length = int(self.val['len'])\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("        return 'Array(len=%d)' % length\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("    def children(self):\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("        length = int(self.val['len'])\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("        ptr = self.val['ptr']\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("        for i in range(length):\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("            yield '[%d]' % i, (ptr + i).dereference()\\n\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("def build_pretty_printer():\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("    pp = gdb.printing.RegexpCollectionPrettyPrinter('tangerine')\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("    pp.add_printer('String', '^tg::String$', TgStringPrinter)\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("    pp.add_printer('Array', '^tg::Array<.*>$', TgArrayPrinter)\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("    return pp\\n\\n"));
    s = tg_str_concat(s, tg_str_from_cstr("gdb.printing.register_pretty_printer(gdb.current_objfile(), build_pretty_printer())\\n"));
    return s;
}

