    tg_println(tg_str_from_cstr("Options:"));
    tg_println(tg_str_from_cstr("  -o, --output <FILE>  Write output to FILE"));
    tg_println(tg_str_from_cstr("  -c                   Compile to object file"));
    tg_println(tg_str_from_cstr("  --emit-obj           Emit object file"));
    tg_println(tg_str_from_cstr("  --emit-mir           Print MIR representation"));
