    tg_println(tg_str_from_cstr("  -v, --verbose        Verbose output"));
    tg_println(tg_str_from_cstr("  -q, --quiet          Quiet output"));
    tg_println(tg_str_from_cstr("  -W, --warn-all       Enable all warnings"));
    tg_println(tg_str_from_cstr("  -Werror              Treat warnings as errors"));
    tg_println(tg_str_from_cstr("  --no-contracts       Disable contract checking"));
