    tg_println(tg_str_from_cstr("  --no-effects         Disable effect system"));
    tg_println(tg_str_from_cstr("  --no-budgets         Disable budget system"));
    tg_println(tg_str_from_cstr("  --target <TRIPLE>    Cross-compile for target (e.g. x86_64-linux-gnu, aarch64-macos)"));
    tg_println(tg_str_from_cstr("  --pgo-gen[=PATH]     Instrument binary for profile generation"));
